function item({ id,capability,cluster,kind = "positive",jurisdiction = "GREAT_BRITAIN",question,context = [],fixture = {},sources,answer,route = "ANSWER",handoff = false,action = false,required = [],prohibited = [],surfaceStructure = null }) {
  if (handoff && !/contact|refer|report|seek|review|security team|legal team|adviser|provider|payroll|bank|independently verified security guidance|FCA Firm Checker/i.test(answer)) throw new Error(`${id} requires a visible handoff in the ideal answer.`);
  const approved = APPROVED_IDS.has(id);
  if (!approved) throw new Error(`Missing reviewer approval for ${id}.`);
  const reviewBasis = EXACT_EDIT_PREAPPROVED_IDS.has(id)
    ? "approved_after_preapproved_exact_edit"
    : SECOND_REVIEW_APPROVED_IDS.has(id) ? "approved_in_second_review" : "approved_after_first_review_mechanical_corrections";
  return {
    training_id:id,capability,failure_cluster:cluster,example_kind:kind,jurisdiction,user_question:question,
    conversation_context:context,synthetic_fixture:{ synthetic:true,contains_real_user_data:false,...fixture },
    retrieved_evidence:sources,ideal_answer:answer,response_route:route,handoff_required:handoff,action_allowed:action,
    required_behaviour:required,prohibited_behaviour:prohibited,source_role:[...new Set(sources.map((entry) => entry.source_role))],
    ...(surfaceStructure ? { surface_structure:surfaceStructure } : {}),
    legal_review_status:reviewBasis,behaviour_review_status:reviewBasis,jurisdiction_review_status:reviewBasis,
    citation_support_review_status:reviewBasis,personal_data_status:"synthetic",human_review_status:"approved_for_phase_6",
    approval_basis:reviewBasis,gold_similarity_check:"pending_refresh",training_eligibility:"approved_manifest_only"
  };
}

