function reviewItem(entry) {
  const rendered = renderCitationMarkers({ answer:entry.ideal_answer,sources:entry.retrieved_evidence.map((evidence) => ({
    sourceId:evidence.source_id,title:evidence.title,citationMetadata:{ kind:evidence.citation_metadata.kind,author:evidence.citation_metadata.author,title:evidence.citation_metadata.title,pinpoint:evidence.citation_metadata.pinpoint,accessedAt:evidence.citation_metadata.accessed_at,userVisible:evidence.citation_metadata.user_visible }
  })) });
  return { ...entry,rendered_answer_preview:rendered.valid ? rendered.answer : null,citation_render_preview_status:rendered.valid ? "passed" : "not_applicable_or_hidden_policy" };
}

