function evidenceSummary(entry) {
  return entry.retrieved_evidence.map((evidence) => {
    const metadata = evidence.citation_metadata;
    return [evidence.title,evidence.source_role,metadata.user_visible === false ? "internal/hidden" : "user-visible metadata",evidence.canonical_url].filter(Boolean).join(" — ");
  }).join("; ");
}

const reviewLines = ["# Phase 5 Targeted Training Review Pack","",`Generated: ${GENERATED_AT}`,"","Status: **All 42 examples are explicitly approved. Phase 6 is authorised but training has not started.**","","Only each item's `ideal_answer` may become the LoRA completion target. Rendered previews are review-only. The deterministic renderer—not the model weights—adds user-visible OSCOLA titles, pinpoints and access dates from source metadata.","","Counts: 42 total — 24 positive, 12 contrast, 6 adversarial; 42 approved, 0 pending, 0 rejected.",""];
